content:
Save the following as `index.html` and open it in a modern browser. It uses only the requested Three.js core ES module and includes custom orbit, pan, zoom, keyboard, and touch controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Bicycle Service Workshop</title>

  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background: #171b1b;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      outline: none;
    }

    #hud {
      position: fixed;
      inset: 0;
      pointer-events: none;
      z-index: 10;
    }

    .title-card {
      position: absolute;
      top: 22px;
      left: 22px;
      max-width: min(390px, calc(100vw - 44px));
      padding: 16px 18px;
      color: #f4eee0;
      background: rgba(20, 24, 24, 0.82);
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 12px;
      box-shadow: 0 12px 35px rgba(0, 0, 0, 0.3);
      backdrop-filter: blur(12px);
    }

    .eyebrow {
      margin: 0 0 5px;
      color: #e3ad4d;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: 0.18em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(20px, 3vw, 29px);
      line-height: 1.1;
      letter-spacing: -0.025em;
    }

    .subtitle {
      margin: 7px 0 0;
      color: #b9c0bd;
      font-size: 12px;
      line-height: 1.45;
    }

    .controls {
      position: absolute;
      right: 20px;
      bottom: 20px;
      display: flex;
      gap: 8px;
      pointer-events: auto;
    }

    button {
      appearance: none;
      padding: 10px 13px;
      color: #f2eee2;
      background: rgba(24, 29, 29, 0.88);
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 9px;
      font: inherit;
      font-size: 12px;
      font-weight: 650;
      cursor: pointer;
      backdrop-filter: blur(10px);
      transition: background 150ms ease, transform 150ms ease;
    }

    button:hover {
      background: rgba(47, 57, 56, 0.96);
      transform: translateY(-1px);
    }

    .help {
      position: absolute;
      left: 22px;
      bottom: 20px;
      padding: 9px 12px;
      color: #c4cacc;
      background: rgba(20, 24, 24, 0.72);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 8px;
      font-size: 11px;
      line-height: 1.45;
      backdrop-filter: blur(8px);
    }

    #loading {
      position: fixed;
      inset: 0;
      z-index: 100;
      display: grid;
      place-items: center;
      color: #e8e0d0;
      background: #171b1b;
      font-size: 13px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      transition: opacity 400ms ease;
    }

    #loading.hidden {
      opacity: 0;
      pointer-events: none;
    }

    @media (max-width: 640px) {
      .title-card {
        top: 12px;
        left: 12px;
        padding: 12px 14px;
      }

      .subtitle {
        display: none;
      }

      .help {
        left: 12px;
        bottom: 68px;
      }

      .controls {
        right: 12px;
        bottom: 12px;
      }
    }
  </style>
</head>

<body>
  <div id="loading">Opening the workshop…</div>

  <div id="hud">
    <section class="title-card">
      <p class="eyebrow">Cycling Studio · Workshop 04</p>
      <h1>Bicycle Service</h1>
      <p class="subtitle">
        Repair stand, wheel truing station, hand tools, hanging tires,
        and organized parts bins.
      </p>
    </section>

    <div class="help">
      Drag to orbit · Wheel to zoom · Right-drag or Shift-drag to pan<br>
      Arrow keys rotate · + / − zoom · R resets the view
    </div>

    <nav class="controls" aria-label="Camera controls">
      <button id="resetView" type="button">Reset view</button>
      <button id="topView" type="button">Top view</button>
    </nav>
  </div>

  <script type="module">
    import * as THREE from
      "https://cdnjs.cloudflare.com/ajax/libs/three.js/0.160.0/three.module.min.js";

    // ---------------------------------------------------------------------
    // Renderer, scene, and camera
    // ---------------------------------------------------------------------

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x171b1b);
    scene.fog = new THREE.Fog(0x171b1b, 15, 30);

    const renderer = new THREE.WebGLRenderer({
      antialias: true,
      powerPreference: "high-performance"
    });

    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.12;
    document.body.appendChild(renderer.domElement);

    const camera = new THREE.PerspectiveCamera(
      43,
      window.innerWidth / window.innerHeight,
      0.08,
      80
    );

    const controls = {
      target: new THREE.Vector3(0, 1.55, -0.55),
      radius: 16.5,
      theta: 0.64,
      phi: 1.28
    };

    function updateCamera() {
      const sinPhi = Math.sin(controls.phi);

      camera.position.set(
        controls.target.x +
          controls.radius * sinPhi * Math.sin(controls.theta),
        controls.target.y + controls.radius * Math.cos(controls.phi),
        controls.target.z +
          controls.radius * sinPhi * Math.cos(controls.theta)
      );

      camera.lookAt(controls.target);
    }

    updateCamera();

    // ---------------------------------------------------------------------
    // Materials and geometry helpers
    // ---------------------------------------------------------------------

    const material = (color, roughness = 0.72, metalness = 0) =>
      new THREE.MeshStandardMaterial({ color, roughness, metalness });

    const M = {
      floor: material(0x303839, 0.96),
      wall: material(0x59615e, 0.92),
      trim: material(0x242a2a, 0.78),
      dark: material(0x171c1d, 0.68, 0.42),
      black: material(0x111515, 0.94),
      rubber: material(0x171a1a, 0.98),
      metal: material(0xaab4b1, 0.3, 0.72),
      brightMetal: material(0xd6dde0, 0.24, 0.8),
      wood: material(0x704327, 0.84),
      benchTop: material(0x8b5a36, 0.72),
      benchLeg: material(0x4b3020, 0.86),
      red: material(0xa8372c, 0.48, 0.18),
      teal: material(0x287c7b, 0.45, 0.18),
      yellow: material(0xd8a63b, 0.56),
      blue: material(0x294e60, 0.5, 0.2),
      cream: material(0xd8d0b7, 0.78),
      paper: material(0xe2d7b8, 0.9),
      green: material(0x355d43, 0.65),
      orange: material(0xc86832, 0.62),
      lamp: new THREE.MeshStandardMaterial({
        color: 0xffe5b2,
        emissive: 0xffc86b,
        emissiveIntensity: 2.2,
        roughness: 0.45
      })
    };

    function addBox(parent, size, position, mat, castShadow = true, receiveShadow = true) {
      const mesh = new THREE.Mesh(
        new THREE.BoxGeometry(size[0], size[1], size[2]),
        mat
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = castShadow;
      mesh.receiveShadow = receiveShadow;
      parent.add(mesh);
      return mesh;
    }

    function addCylinder(
      parent,
      radiusTop,
      radiusBottom,
      height,
      position,
      mat,
      segments = 16
    ) {
      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments),
        mat
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addRod(parent, a, b, radius, mat) {
      const start = a.isVector3 ? a : new THREE.Vector3(...a);
      const end = b.isVector3 ? b : new THREE.Vector3(...b);
      const direction = end.clone().sub(start);
      const length = direction.length();

      const mesh = new THREE.Mesh(
        new THREE.CylinderGeometry(radius, radius, length, 10),
        mat
      );

      mesh.position.copy(start).add(end).multiplyScalar(0.5);
      mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
      );
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addTorus(
      parent,
      radius,
      tube,
      position,
      mat,
      radialSegments = 10,
      tubularSegments = 48
    ) {
      const mesh = new THREE.Mesh(
        new THREE.TorusGeometry(
          radius,
          tube,
          radialSegments,
          tubularSegments
        ),
        mat
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    function addSphere(parent, radius, position, mat) {
      const mesh = new THREE.Mesh(
        new THREE.SphereGeometry(radius, 16, 12),
        mat
      );
      mesh.position.set(position[0], position[1], position[2]);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      parent.add(mesh);
      return mesh;
    }

    // ---------------------------------------------------------------------
    // Workshop shell
    // ---------------------------------------------------------------------

    addBox(scene, [11.2, 0.24, 13.2], [0, -0.12, 0], M.floor);
    addBox(scene, [11.2, 6, 0.22], [0, 3, -6.15], M.wall);
    addBox(scene, [0.22, 6, 13.2], [-5.55, 3, 0], M.wall);
    addBox(scene, [0.22, 1.05, 13.2], [5.55, 0.525, 0], M.wall);

    // Low front wall on the right preserves the cutaway interior view.
    addBox(scene, [0.22, 1.05, 2.4], [5.55, 0.525, -4.55], M.wall);

    addBox(scene, [11, 0.12, 0.12], [0, 0.08, -5.98], M.trim);
    addBox(scene, [0.12, 0.12, 13], [-5.38, 0.08, 0], M.trim);
    addBox(scene, [0.12, 0.12, 13], [5.38, 0.08, 0], M.trim);

    // Floor lane markings.
    addBox(scene, [0.055, 0.012, 11.5], [-4.65, 0.012, 0.5], M.yellow, false, false);
    addBox(scene, [0.055, 0.012, 11.5], [4.65, 0.012, 0.5], M.yellow, false, false);

    // Wall columns and overhead beam.
    addBox(scene, [0.28, 5.8, 0.3], [-5.3, 2.9, -5.8], M.trim);
    addBox(scene, [0.28, 5.8, 0.3], [5.3, 2.9, -5.8], M.trim);
    addBox(scene, [10.8, 0.16, 0.22], [0, 5.55, -1.5], M.trim);

    // Ceiling lights.
    for (const z of [-2.8, 1.3]) {
      addBox(scene, [2.5, 0.12, 0.34], [-0.8, 5.35, z], M.dark);
      addBox(
        scene,
        [2.15, 0.055, 0.22],
        [-0.8, 5.25, z],
        M.lamp,
        false,
        false
      );

      const light = new THREE.PointLight(0xffd9a0, 24, 8, 2);
      light.position.set(-0.8, 4.95, z);
      scene.add(light);
    }

    // ---------------------------------------------------------------------
    // Pegboard panels and hand tools
    // ---------------------------------------------------------------------

    function makePegboardTexture() {
      const canvas = document.createElement("canvas");
      canvas.width = 512;
      canvas.height = 512;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#9b7043";
      ctx.fillRect(0, 0, 512, 512);

      const cell = 24;
      const offset = 0;

      for (let row = 0; row < 23; row++) {
        for (let col = 0; col < 21; col++) {
          const x = col * cell + offset;
          const y = row * cell;
          const gradient = ctx.createRadialGradient(
            x + 3,
            y + 3,
            0,
            x,
            y,
            5
          );
          gradient.addColorStop(0, "rgba(35,24,13,0.88)");
          gradient.addColorStop(1, "rgba(35,24,13,0)");
          ctx.fillStyle = gradient;
          ctx.beginPath();
          ctx.arc(x, y, 3.2, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      ctx.strokeStyle = "rgba(60,40,20,0.25)";
      ctx.lineWidth = 2;
      for (let i = 0; i <= 512; i += cell) {
        ctx.beginPath();
        ctx.moveTo(i, 0);
        ctx.lineTo(i, 512);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(0, i);
        ctx.lineTo(512, i);
        ctx.stroke();
      }

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
      return texture;
    }

    const pegTexture = makePegboardTexture();

    function makePegboard(x, width, y, height) {
      addBox(
        scene,
        [width + 0.1, height + 0.1, 0.1],
        [x, y, -6.03],
        M.wood
      );

      const board = new THREE.Mesh(
        new THREE.PlaneGeometry(width, height),
        new THREE.MeshStandardMaterial({
          map: pegTexture,
          roughness: 1
        })
      );
      board.position.set(x, y, -5.965);
      board.receiveShadow = true;
      scene.add(board);
      return board;
    }

    makePegboard(-2.72, 3.35, 3.35, 2.25);
    makePegboard(3.05, 2.2, 3.35, 2.25);

    function addWrench(x, y, z) {
      addRod(scene, [x, y, z], [x, y + 0.28, z], 0.026, M.metal);
      addRod(scene, [x - 0.18, y + 0.25, z], [x, y + 0.43, z], 0.027, M.metal);
      addRod(scene, [x + 0.18, y + 0.25, z], [x, y + 0.43, z], 0.027, M.metal);
      addRod(scene, [x - 0.18, y + 0.25, z], [x, y + 0.12, z], 0.025, M.metal);
      addRod(scene, [x + 0.18, y + 0.25, z], [x, y + 0.12, z], 0.025, M.metal);
    }

    function addHammer(x, y, z) {
      addRod(scene, [x, y, z], [x, y + 0.46, z], 0.025, M.wood);
      addBox(scene, [0.28, 0.12, 0.12], [x, y + 0.5, z], M.metal);
      addBox(scene, [0.34, 0.06, 0.14], [x, y + 0.5, z], M.dark);
    }

    function addScrewdriver(x, y, z, color = M.red) {
      addCylinder(scene, 0.055, 0.07, 0.18, [x, y + 0.09, z], color);
      addRod(scene, [x, y + 0.18, z], [x, y + 0.55, z], 0.018, M.metal);
      addRod(scene, [x, y + 0.55, z], [x + 0.12, y + 0.55, z], 0.026, M.metal);
    }

    function addPliers(x, y, z) {
      addRod(scene, [x - 0.08, y, z], [x + 0.08, y + 0.28, z], 0.022, M.metal);
      addRod(scene, [x + 0.08, y, z], [x - 0.08, y + 0.28, z], 0.022, M.metal);
      addRod(scene, [x - 0.12, y, z], [x - 0.3, y - 0.12, z], 0.025, M.dark);
      addRod(scene, [x + 0.12, y, z], [x + 0.3, y - 0.12, z], 0.025, M.dark);
    }

    function addGlueBottle(x, y, z) {
      addCylinder(scene, 0.095, 0.11, 0.28, [x, y + 0.14, z], M.cream);
      addCylinder(scene, 0.06, 0.075, 0.09, [x, y + 0.34, z], M.red);
      addCylinder(scene, 0.055, 0.055, 0.025, [x, y + 0.405, z], M.dark);
    }

    function addSprayCan(x, y, z) {
      addCylinder(scene, 0.11, 0.13, 0.28, [x, y + 0.14, z], M.teal);
      addCylinder(scene, 0.035, 0.035, 0.13, [x, y + 0.34, z], M.metal);
      addRod(scene, [x, y + 0.41, z], [x + 0.1, y + 0.41, z], 0.02, M.black);
    }

    function addTorqueWrench(x, y, z) {
      addCylinder(scene, 0.085, 0.1, 0.25, [x, y + 0.12, z], M.yellow);
      addRod(scene, [x, y + 0.25, z], [x, y + 0.48, z], 0.025, M.dark);
      addRod(scene, [x, y + 0.48, z], [x + 0.18, y + 0.48, z], 0.027, M.metal);
    }

    const toolPositions = [
      [-3.75, 3.35],
      [-3.18, 3.35],
      [-2.62, 3.55],
      [-2.12, 3.35],
      [3.48, 3.35],
      [3.05, 3.62],
      [2.63, 3.35]
    ];

    toolPositions.forEach(([x, y], index) => {
      if (index === 0) addWrench(x, y, -5.82);
      if (index === 1) addHammer(x, y, -5.82);
      if (index === 2) addScrewdriver(x, y, -5.82, M.red);
      if (index === 3) addPliers(x, y, -5.82);
      if (index === 4) addGlueBottle(x, y, -5.82);
      if (index === 5) addSprayCan(x, y, -5.82);
      if (index === 6) addTorqueWrench(x, y, -5.82);
    });

    // Wall sign.
    function makeSignTexture(title, subtitle) {
      const canvas = document.createElement("canvas");
      canvas.width = 1024;
      canvas.height = 256;
      const ctx = canvas.getContext("2d");

      ctx.fillStyle = "#171d1d";
      ctx.fillRect(0, 0, 1024, 256);
      ctx.strokeStyle = "#d8a64f";
      ctx.lineWidth = 8;
      ctx.strokeRect(12, 12, 1000, 232);

      ctx.textAlign = "center";
      ctx.fillStyle = "#eee5d2";
      ctx.font = "700 76px sans-serif";
      ctx.fillText(title, 512, 112);

      ctx.fillStyle = "#b9b9a7";
      ctx.font = "500 30px sans-serif";
      ctx.fillText(subtitle, 512, 173);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      return texture;
    }

    const sign = new THREE.Mesh(
      new THREE.PlaneGeometry(3.65, 0.92),
      new THREE.MeshBasicMaterial({
        map: makeSignTexture("BICYCLE SERVICE", "REPAIR  ·  TRUING  ·  FIT")
      })
    );
    sign.position.set(0, 4.28, -5.84);
    scene.add(sign);

    // ---------------------------------------------------------------------
    // Hanging tires
    // ---------------------------------------------------------------------

    function addHook(x, y, z) {
      const curve = new THREE.CatmullRomCurve3([
        new THREE.Vector3(x + 0.55, y, z),
        new THREE.Vector3(x + 0.55, y + 0.1, z + 0.04),
        new THREE.Vector3(x + 0.45, y + 0.2, z + 0.08)
      ]);

      const hook = new THREE.Mesh(
        new THREE.TubeGeometry(curve, 18, 0.018, 7, false),
        M.metal
      );
      hook.castShadow = true;
      scene.add(hook);
    }

    function makeHangingTire(x, labelX) {
      addHook(x, 3.68, -5.78);

      const tire = addTorus(
        scene,
        0.55,
        0.065,
        [x, 3.08, -5.52],
        M.rubber,
        12,
        56
      );
      tire.rotation.z = -0.08;

      addTorus(
        scene,
        0.485,
        0.027,
        [x, 3.08, -5.45],
        M.metal,
        10,
        48
      );

      addCylinder(
        scene,
        0.012,
        0.012,
        0.2,
        [x + 0.55, 3.61, -5.5],
        M.black,
        8
      );

      addBox(
        scene,
        [0.22, 0.1, 0.03],
        [labelX, 3.1, -5.43],
        M.yellow
      );
    }

    makeHangingTire(-0.25, -0.25);
    makeHangingTire(1.1, 1.1);

    // ---------------------------------------------------------------------
    // Workbench along the left wall
    // ---------------------------------------------------------------------

    const bench = new THREE.Group();
    scene.add(bench);

    addBox(bench, [2.45, 0.16, 5.8], [-3.8, 1.35, 0.15], M.benchTop);
    addBox(bench, [2.1, 0.12, 5.5], [-3.8, 0.35, 0.15], M.wood);

    for (const x of [-4.55, -3.05]) {
      for (const z of [-2.25, 2.55]) {
        addBox(bench, [0.16, 1.25, 0.16], [x, 0.62, z], M.benchLeg);
      }
    }

    // Drawer fronts on the camera-facing side.
    addBox(bench, [0.08, 0.62, 5.35], [-2.62, 0.72, 0.15], M.wood);
    for (let z = -1.95; z <= 2.2; z += 1.3) {
      addBox(bench, [0.045, 0.11, 0.42], [-2.56, 0.75, z], M.metal);
    }

    // Bench vise.
    addBox(bench, [0.42, 0.3, 0.5], [-3.8, 1.5, -1.65], M.dark);
    addRod(
      bench,
      [-4.03, 1.62, -1.65],
      [-4.03, 2.0, -1.65],
      0.055,
      M.metal
    );
    addRod(
      bench,
      [-4.03, 2.0, -1.65],
      [-3.62, 2.0, -1.65],
      0.055,
      M.metal
    );
    addRod(
      bench,
      [-3.62, 2.0, -1.65],
      [-3.62, 1.55, -1.65],
      0.055,
      M.metal
    );

    // Bench tools and parts.
    addCylinder(bench, 0.09, 0.11, 0.28, [-4.25, 1.5, 1.3], M.cream);
    addCylinder(bench, 0.06, 0.065, 0.09, [-4.25, 1.66, 1.3], M.red);

    addBox(bench, [0.38, 0.055, 0.24], [-3.05, 1.45, 1.9], M.dark);
    addBox(bench, [0.28, 0.04, 0.18], [-2.88, 1.49, 1.9], M.metal);

    // Coiled cable on the bench.
    const cable = addTorus(
      bench,
      0.22,
      0.025,
      [-3.95, 1.47, -0.5],
      M.black,
      8,
      36
    );
    cable.rotation.x = Math.PI / 2;

    // Floor mat.
    addBox(scene, [3.25, 0.025, 2.05], [-1.2, 0.025, 2.65], M.teal, false, true);
    for (const x of [-2.35, -0.05]) {
      addBox(scene, [0.035, 0.008, 1.85], [x, 0.042, 2.65], M.dark, false, false);
    }

    // Stool.
    const stool = new THREE.Group();
    stool.position.set(-3.8, 0, 3.55);
    scene.add(stool);

